<?php
require_once __DIR__.'/includes/auth.php';require_auth();$u=current_user();$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){ $name=trim((string)($_POST['name']??''));if($name==='')flash('danger','Collection name is required.');else{db()->prepare('INSERT INTO collections(name,description,owner_id,visibility) VALUES(?,?,?,?)')->execute([mb_substr($name,0,160),trim((string)($_POST['description']??'')),$u['id'],in_array($_POST['visibility']??'', ['private','organization'],true)?$_POST['visibility']:'private']);audit('collection_created','Created collection “'.$name.'”.');flash('success','Collection created.');}}
 elseif($action==='delete'){ $cid=(int)($_POST['collection_id']??0);db()->prepare('DELETE FROM collections WHERE id=? AND owner_id=?')->execute([$cid,$u['id']]);flash('success','Collection deleted.');if($id===$cid)redirect('collections.php');}
 elseif($action==='remove_asset'){ $cid=(int)($_POST['collection_id']??0);$aid=(int)($_POST['asset_id']??0);db()->prepare('DELETE ca FROM collection_assets ca JOIN collections c ON c.id=ca.collection_id WHERE ca.collection_id=? AND ca.asset_id=? AND c.owner_id=?')->execute([$cid,$aid,$u['id']]);flash('success','Asset removed from collection.');}
 elseif($action==='share_user'){ $cid=(int)($_POST['collection_id']??0);$userId=(int)($_POST['user_id']??0);$permission=in_array($_POST['permission']??'', ['view','download'],true)?$_POST['permission']:'view';$check=db()->prepare('SELECT 1 FROM collections WHERE id=? AND owner_id=?');$check->execute([$cid,$u['id']]);if($check->fetchColumn()&&$userId!==$u['id']){db()->prepare('INSERT INTO collection_shares(collection_id,user_id,permission) VALUES(?,?,?) ON DUPLICATE KEY UPDATE permission=VALUES(permission)')->execute([$cid,$userId,$permission]);notification($userId,'Collection shared with you','“'.(string)($_POST['collection_name']??'A collection').'” was shared with you.','collections.php?id='.$cid);flash('success','Collection shared.');}}
 redirect('collections.php'.($id?'?id='.$id:''));
}
$mine=db()->prepare("SELECT c.*,COUNT(DISTINCT ca.asset_id) asset_count,COUNT(DISTINCT cs.user_id) shared_count FROM collections c LEFT JOIN collection_assets ca ON ca.collection_id=c.id LEFT JOIN collection_shares cs ON cs.collection_id=c.id WHERE c.owner_id=? GROUP BY c.id ORDER BY c.updated_at DESC");$mine->execute([$u['id']]);$myCollections=$mine->fetchAll();
$shared=db()->prepare("SELECT c.*,u.name owner_name,COUNT(ca.asset_id) asset_count,cs.permission FROM collections c JOIN users u ON u.id=c.owner_id LEFT JOIN collection_assets ca ON ca.collection_id=c.id LEFT JOIN collection_shares cs ON cs.collection_id=c.id AND cs.user_id=? WHERE c.owner_id<>? AND (c.visibility='organization' OR cs.user_id IS NOT NULL) GROUP BY c.id,cs.permission ORDER BY c.updated_at DESC");$shared->execute([$u['id'],$u['id']]);$sharedCollections=$shared->fetchAll();$all=array_merge($myCollections,$sharedCollections);
$collection=null;$collectionAssets=[];$isOwner=false;if($id){foreach($all as $c)if((int)$c['id']===$id)$collection=$c;if(!$collection){http_response_code(404);exit('Collection not found.');}$isOwner=(int)$collection['owner_id']===(int)$u['id'];$a=db()->prepare("SELECT a.*,u.name uploader_name,c.name category_name FROM collection_assets ca JOIN assets a ON a.id=ca.asset_id JOIN users u ON u.id=a.uploaded_by LEFT JOIN categories c ON c.id=a.category_id WHERE ca.collection_id=? AND a.deleted_at IS NULL ORDER BY ca.created_at DESC");$a->execute([$id]);$collectionAssets=$a->fetchAll();}
$users=$id&&$isOwner?db()->prepare('SELECT id,name,email FROM users WHERE id<>? AND status=\'active\' AND deleted_at IS NULL ORDER BY name'):null;if($users){$users->execute([$u['id']]);$users=$users->fetchAll();}
$pageTitle=$collection?$collection['name']:'Collections';$pageSubtitle=$collection?($collection['description']?:'Curated digital assets'):'Curate assets for projects, campaigns and teams';$pageActions='<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#createCollection"><i class="bi bi-plus-lg me-1"></i>New collection</button>';require __DIR__.'/includes/header.php';?>
<?php if($collection):?><div class="d-flex justify-content-between mb-3"><a href="<?=e(url('collections.php'))?>" class="btn btn-light"><i class="bi bi-arrow-left me-1"></i>All collections</a><?php if($isOwner):?><div class="d-flex gap-2"><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#shareCollection"><i class="bi bi-person-plus me-1"></i>Share</button><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="collection_id" value="<?=$id?>"><button class="btn btn-outline-danger" data-confirm="Delete this collection? Assets will not be deleted.">Delete</button></form></div><?php endif;?></div><div class="row g-4"><?php foreach($collectionAssets as $a):?><div class="col-sm-6 col-lg-4 col-xl-3"><div class="card asset-card h-100"><a class="asset-thumb" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?php if(in_array($a['file_extension'],['jpg','jpeg','png','gif','webp'],true)):?><img src="<?=e(url('preview.php?id='.$a['id']))?>" alt=""><?php else:?><i class="bi <?=e(asset_icon($a['file_extension']))?>"></i><?php endif;?></a><div class="card-body"><a class="fw-semibold text-dark text-decoration-none" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?=e($a['title'])?></a><small class="d-block text-muted"><?=e(human_file_size((int)$a['file_size']))?></small><?php if($isOwner):?><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="remove_asset"><input type="hidden" name="collection_id" value="<?=$id?>"><input type="hidden" name="asset_id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php endif;?></div></div></div><?php endforeach;?><?php if(!$collectionAssets):?><div class="col-12"><div class="card"><div class="empty-state"><i class="bi bi-collection"></i><h2 class="h5 mt-3">This collection is empty</h2><p>Add assets from an asset details page.</p></div></div></div><?php endif;?></div><?php else:?><h2 class="h6 text-muted mb-3">My collections</h2><div class="row g-4 mb-5"><?php foreach($myCollections as $c):?><div class="col-md-6 col-xl-4"><a class="card h-100 text-decoration-none text-dark" href="<?=e(url('collections.php?id='.$c['id']))?>"><div class="card-body p-4"><div class="stat-icon bg-primary bg-opacity-10 text-primary mb-3"><i class="bi bi-collection"></i></div><h2 class="h5"><?=e($c['name'])?></h2><p class="text-muted small text-truncate"><?=e($c['description']?:'No description')?></p><span class="small"><?=$c['asset_count']?> assets · <?=$c['shared_count']?> collaborators</span></div></a></div><?php endforeach;?><?php if(!$myCollections):?><div class="col-12 text-muted">You have not created a collection yet.</div><?php endif;?></div><?php if($sharedCollections):?><h2 class="h6 text-muted mb-3">Shared with me</h2><div class="row g-4"><?php foreach($sharedCollections as $c):?><div class="col-md-6 col-xl-4"><a class="card h-100 text-decoration-none text-dark" href="<?=e(url('collections.php?id='.$c['id']))?>"><div class="card-body p-4"><h2 class="h5"><?=e($c['name'])?></h2><p class="small text-muted"><?=e($c['owner_name'])?> · <?=$c['asset_count']?> assets</p></div></a></div><?php endforeach;?></div><?php endif;?><?php endif;?>
<div class="modal fade" id="createCollection"><div class="modal-dialog"><div class="modal-content"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="modal-header"><h2 class="modal-title fs-5">New collection</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Name</label><input class="form-control mb-3" name="name" required maxlength="160"><label class="form-label">Description</label><textarea class="form-control mb-3" name="description"></textarea><label class="form-label">Visibility</label><select class="form-select" name="visibility"><option value="private">Private</option><option value="organization">Organization</option></select></div><div class="modal-footer"><button class="btn btn-primary">Create collection</button></div></form></div></div></div>
<?php if($collection&&$isOwner):?><div class="modal fade" id="shareCollection"><div class="modal-dialog"><div class="modal-content"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="share_user"><input type="hidden" name="collection_id" value="<?=$id?>"><input type="hidden" name="collection_name" value="<?=e($collection['name'])?>"><div class="modal-header"><h2 class="modal-title fs-5">Share collection</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">User</label><select class="form-select mb-3" name="user_id" required><?php foreach($users as $row):?><option value="<?=$row['id']?>"><?=e($row['name'].' · '.$row['email'])?></option><?php endforeach;?></select><label class="form-label">Permission</label><select class="form-select" name="permission"><option value="view">View only</option><option value="download">View and download</option></select></div><div class="modal-footer"><button class="btn btn-primary">Share</button></div></form></div></div></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>

